-- Reference schema for the webhook tables (PostgreSQL).
-- The app creates these automatically from the EF Core model (EnsureCreated);
-- this file documents them and the constraints that make processing idempotent.

CREATE TABLE "WebhookEvents" (
    "Id"         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EventId"    character varying(100) NOT NULL,
    "EventType"  character varying(100) NOT NULL,
    "ReceivedAt" timestamp with time zone NOT NULL
);

-- The idempotency guarantee: the same event id can be stored only once
CREATE UNIQUE INDEX "IX_WebhookEvents_EventId" ON "WebhookEvents" ("EventId");

CREATE TABLE "OutboxMessages" (
    "Id"            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "EventId"       character varying(100) NOT NULL,
    "Type"          character varying(100) NOT NULL,
    "Payload"       character varying(2000) NOT NULL,
    "CreatedAt"     timestamp with time zone NOT NULL,
    "NextAttemptAt" timestamp with time zone NOT NULL,
    "ProcessedAt"   timestamp with time zone NULL,
    "Attempts"      integer NOT NULL,
    "LastError"     character varying(500) NULL
);

-- One outbox message per event, so retries can never create a second one
CREATE UNIQUE INDEX "IX_OutboxMessages_EventId" ON "OutboxMessages" ("EventId");
